    hints: [
      { tier: 1, content: "Pick `alu_op` with the opcode: `(opcode == OP) ? {instr[30], funct3} : (opcode == OPIMM) ? {(funct3 == 3'b101) ? instr[30] : 1'b0, funct3} : 4'b0000`." },
      { tier: 2, content: "`alu_b` is `rv2` for OP and `imm` otherwise. `wb_data` is the ALU result, `imm` for LUI, or `pc + imm` for AUIPC." },
      { tier: 3, content: "`assign wb_en = !rst && (opcode == OP || opcode == OPIMM || opcode == LUI || opcode == AUIPC);` and the PC register adds 4 every cycle." }
    ],
    solutionExplanation: "A single-cycle CPU is one big combinational path from the PC to the register write: fetch (`imem_data`), decode\n(opcode, register numbers, immediate), read registers, compute, and write back on the clock edge, when the PC also advances.\n\nThe OP-IMM trap is real: RISC-V reuses bit 30 as an immediate bit in ADDI, so `addi x3, x0, -1024` has bit 30 set and would turn into\na subtraction if you decoded it like a register instruction. AUIPC uses the PC of its own instruction, which is how position-independent\ncode finds addresses.",
    publicTestcases: [], hiddenTestcases: [],
    starterCode: "`timescale 1ns / 1ps\n\n// @step rv-alu\nmodule rv_alu (\n    input  wire [31:0] a,\n    input  wire [31:0] b,\n    input  wire [3:0]  op,\n    output wire [31:0] y,\n    output wire        zero\n);\n    assign y = 32'd0;\n    assign zero = 1'b1;\nendmodule\n// @end\n\n// @step rv-regfile\nmodule rv_regfile (\n    input  wire        clk,\n    input  wire        we,\n    input  wire [4:0]  rs1,\n    input  wire [4:0]  rs2,\n    input  wire [4:0]  rd,\n    input  wire [31:0] wd,\n    output wire [31:0] rd1,\n    output wire [31:0] rd2\n);\n    assign rd1 = 32'd0;\n    assign rd2 = 32'd0;\nendmodule\n// @end\n\n// @step rv-immgen\nmodule rv_immgen (\n    input  wire [31:0] instr,\n    output wire [31:0] imm\n);\n    assign imm = 32'd0;\nendmodule\n// @end\n\n// RISC-V step 5: your first CPU. Runs OP, OP-IMM, LUI and AUIPC instructions.\nmodule rv_cpu (\n    input  wire        clk,\n    input  wire        rst,          // synchronous, active high\n    output wire [31:0] imem_addr,    // address of the instruction to fetch\n    input  wire [31:0] imem_data,    // the instruction (combinational read)\n    output wire [31:0] dmem_addr,    // load/store byte address\n    output wire [31:0] dmem_wdata,   // store data\n    output wire        dmem_we,      // 1 = store this cycle\n    input  wire [31:0] dmem_rdata,   // load data (combinational read)\n    output wire        wb_en,        // 1 = this instruction writes register wb_rd\n    output wire [4:0]  wb_rd,\n    output wire [31:0] wb_data\n);\n    localparam OP = 7'b0110011, OPIMM = 7'b0010011, LUI = 7'b0110111, AUIPC = 7'b0010111;\n\n    reg  [31:0] pc;\n    wire [31:0] instr  = imem_data;\n    wire [6:0]  opcode = instr[6:0];\n    wire [2:0]  funct3 = instr[14:12];\n    wire [4:0]  rd = instr[11:7], rs1 = instr[19:15], rs2 = instr[24:20];\n\n    wire [31:0] imm, rv1, rv2, alu_y;\n    wire        alu_zero;\n    rv_immgen  u_imm (.instr(instr), .imm(imm));\n    rv_regfile u_rf  (.clk(clk), .we(wb_en), .rs1(rs1), .rs2(rs2), .rd(rd), .wd(wb_data), .rd1(rv1), .rd2(rv2));\n\n    // TODO: choose the ALU operation and second operand from the instruction\n    wire [3:0]  alu_op = 4'b0000;\n    wire [31:0] alu_b  = rv2;\n    rv_alu     u_alu (.a(rv1), .b(alu_b), .op(alu_op), .y(alu_y), .zero(alu_zero));\n\n    // TODO: write back for OP, OP-IMM, LUI and AUIPC (and never while rst is high)\n    assign wb_en   = 1'b0;\n    assign wb_rd   = rd;\n    assign wb_data = alu_y;\n\n    assign imem_addr  = pc;\n    assign dmem_addr  = 32'd0;      // memory comes in the next step\n    assign dmem_wdata = 32'd0;\n    assign dmem_we    = 1'b0;\n\n    always @(posedge clk) begin\n        if (rst) pc <= 32'd0;\n        else     pc <= pc + 32'd4;   // straight-line code only, for now\n    end\nendmodule\n",
    publicTestbench: "`timescale 1ns / 1ps\nmodule tb_rv_datapath;\n    reg clk = 0, rst = 1;\n    always #5 clk = ~clk;\n    wire [31:0] imem_addr, dmem_addr, dmem_wdata, wb_data;\n    wire        dmem_we, wb_en;\n    wire [4:0]  wb_rd;\n    reg  [31:0] imem [0:255];       // instruction memory (word index = imem_addr[9:2])\n    reg  [31:0] dmem [0:255];       // data memory        (word index = dmem_addr[9:2])\n    reg  [31:0] shadow [0:31];      // register values seen on the write-back port\n    reg  [31:0] exp_reg [0:31];\n    reg  [31:0] exp_mem [0:255];\n    integer i, errors = 0;\n    rv_cpu dut (.clk(clk), .rst(rst),\n                .imem_addr(imem_addr), .imem_data(imem[imem_addr[9:2]]),\n                .dmem_addr(dmem_addr), .dmem_wdata(dmem_wdata), .dmem_we(dmem_we), .dmem_rdata(dmem[dmem_addr[9:2]]),\n                .wb_en(wb_en), .wb_rd(wb_rd), .wb_data(wb_data));\n    initial begin $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_rv_datapath); end\n    always @(posedge clk) begin\n        if (rst) begin\n            if (wb_en !== 1'b0 || dmem_we !== 1'b0) begin\n                errors = errors + 1;\n                if (errors <= 3) $display(\"FAIL: wb_en and dmem_we must be 0 while rst is high\");\n            end\n        end else begin\n            if (dmem_we) dmem[dmem_addr[9:2]] <= dmem_wdata;\n            if (wb_en && wb_rd != 5'd0) shadow[wb_rd] <= wb_data;\n            if (wb_en && wb_rd != 5'd0) $display(\"  x%0d <= 0x%08h\", wb_rd, wb_data);\n        end\n    end\n    task clear;\n        begin\n            for (i = 0; i < 256; i = i + 1) begin imem[i] = 32'h00000013; dmem[i] = 32'd0; exp_mem[i] = 32'd0; end\n            for (i = 0; i < 32; i = i + 1) begin shadow[i] = 32'd0; exp_reg[i] = 32'd0; end\n        end\n    endtask\n    task reset_cpu;\n        begin rst = 1; @(posedge clk); @(posedge clk); #1 rst = 0; end\n    endtask\n    task compare(input [8*12:1] prog);\n        begin\n            for (i = 1; i < 32; i = i + 1)\n                if (shadow[i] !== exp_reg[i]) begin\n                    errors = errors + 1;\n                    $display(\"FAIL: program %0s: x%0d = 0x%08h, expected 0x%08h\", prog, i, shadow[i], exp_reg[i]);\n                end\n            for (i = 0; i < 256; i = i + 1)\n                if (dmem[i] !== exp_mem[i]) begin\n                    errors = errors + 1;\n                    $display(\"FAIL: program %0s: mem[0x%03h] = 0x%08h, expected 0x%08h\", prog, i * 4, dmem[i], exp_mem[i]);\n                end\n        end\n    endtask\n    initial begin\n        // Program \"fibonacci\"\n        clear;\n        imem[0] = 32'h00100093;\n        imem[1] = 32'h00100113;\n        imem[2] = 32'h002081b3;\n        imem[3] = 32'h00310233;\n        imem[4] = 32'h004182b3;\n        imem[5] = 32'h00520333;\n        imem[6] = 32'h006283b3;\n        imem[7] = 32'h00730433;\n        reset_cpu;\n        repeat (10) @(posedge clk);\n        #1;\n        $display(\"--- final register values ---\");\n        $display(\"x%0d = 0x%08h (expected 0x00000001)\", 1, shadow[1]);\n        $display(\"x%0d = 0x%08h (expected 0x00000001)\", 2, shadow[2]);\n        $display(\"x%0d = 0x%08h (expected 0x00000002)\", 3, shadow[3]);\n        $display(\"x%0d = 0x%08h (expected 0x00000003)\", 4, shadow[4]);\n        $display(\"x%0d = 0x%08h (expected 0x00000005)\", 5, shadow[5]);\n        $display(\"x%0d = 0x%08h (expected 0x00000008)\", 6, shadow[6]);\n        $display(\"x%0d = 0x%08h (expected 0x0000000d)\", 7, shadow[7]);\n        $display(\"x%0d = 0x%08h (expected 0x00000015)\", 8, shadow[8]);\n        $finish;\n    end\nendmodule\n",
